def transform(grid):
    H = len(grid)
    W = len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = min(counts, key=lambda x: (counts[x], x))

    seen = [[False] * W for _ in range(H)]
    boxes = []
    keys = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == bg or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < H and 0 <= nx < W and not seen[ny][nx] and grid[ny][nx] != bg:
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            if len(cells) == 1:
                keys.append((r, c, grid[r][c]))
                continue
            ys = [p[0] for p in cells]
            xs = [p[1] for p in cells]
            r0, r1 = min(ys), max(ys)
            c0, c1 = min(xs), max(xs)
            interior = []
            for y in range(r0 + 1, r1):
                for x in range(c0 + 1, c1):
                    v = grid[y][x]
                    if v != bg:
                        interior.append((y, x, v))
            if interior:
                col_counts = {}
                for _, _, v in interior:
                    col_counts[v] = col_counts.get(v, 0) + 1
                item = max(col_counts, key=lambda v: (col_counts[v], v))
                cells2 = [(y, x) for y, x, v in interior if v == item]
                boxes.append({"color": item, "cells": cells2,
                              "r0": r0, "r1": r1, "c0": c0, "c1": c1})

    if keys:
        kr = min(k[0] for k in keys)
        key_vals = [v for r, c, v in sorted(keys, key=lambda p: (p[0], p[1])) if r == kr]
    else:
        key_vals = []

    out = [row[:] for row in grid]

    def box_for_color(color, boxes, prev_box=None, next_box=None):
        cands = [b for b in boxes if b["color"] == color]
        if len(cands) == 1:
            return cands[0]
        best, best_dist = None, None
        for b in cands:
            dist = 0
            if prev_box is not None:
                if b["r0"] == prev_box["r1"] and not (b["c1"] < prev_box["c0"] or b["c0"] > prev_box["c1"]):
                    pass
                elif b["c0"] == prev_box["c1"] and not (b["r1"] < prev_box["r0"] or b["r0"] > prev_box["r1"]):
                    pass
                else:
                    dr = max(prev_box["r0"] - b["r1"], b["r0"] - prev_box["r1"], 0)
                    dc = max(prev_box["c0"] - b["c1"], b["c0"] - prev_box["c1"], 0)
                    if dr == 0:
                        dist += dc
                    elif dc == 0:
                        dist += dr
                    else:
                        dist += dr + dc + 1000
            if next_box is not None:
                if b["r1"] == next_box["r0"] and not (b["c1"] < next_box["c0"] or b["c0"] > next_box["c1"]):
                    pass
                elif b["c1"] == next_box["c0"] and not (b["r1"] < next_box["r0"] or b["r0"] > next_box["r1"]):
                    pass
                else:
                    dr = max(next_box["r0"] - b["r1"], b["r0"] - next_box["r1"], 0)
                    dc = max(next_box["c0"] - b["c1"], b["c0"] - next_box["c1"], 0)
                    if dr == 0:
                        dist += dc
                    elif dc == 0:
                        dist += dr
                    else:
                        dist += dr + dc + 1000
            if best_dist is None or dist < best_dist:
                best, best_dist = b, dist
        return best

    for i in range(len(key_vals) - 1):
        a, b = key_vals[i], key_vals[i + 1]
        src = box_for_color(a, boxes)
        tgt = box_for_color(b, boxes, src)
        if src is None or tgt is None:
            continue
        src_cells = src["cells"]
        tgt_cells = tgt["cells"]
        sy = sum(p[0] for p in src_cells) // len(src_cells)
        sx = sum(p[1] for p in src_cells) // len(src_cells)
        ty = sum(p[0] for p in tgt_cells) // len(tgt_cells)
        tx = sum(p[1] for p in tgt_cells) // len(tgt_cells)
        if sy == ty:
            lo, hi = sorted((sx, tx))
            for x in range(lo + 1, hi):
                if out[sy][x] == bg:
                    out[sy][x] = src["color"]
        elif sx == tx:
            lo, hi = sorted((sy, ty))
            for y in range(lo + 1, hi):
                if out[y][sx] == bg:
                    out[y][sx] = src["color"]
        else:
            if src["r0"] < tgt["r0"]:
                if src["c0"] == tgt["c1"] and not (src["r1"] < tgt["r0"] or src["r0"] > tgt["r1"]):
                    x = src["c1"]
                    lo, hi = sorted((src["r0"], tgt["r1"]))
                    for y in range(lo + 1, hi):
                        if out[y][x] == bg:
                            out[y][x] = src["color"]
            elif tgt["r0"] < src["r0"]:
                if tgt["c0"] == src["c1"] and not (tgt["r1"] < src["r0"] or tgt["r0"] > src["r1"]):
                    x = tgt["c1"]
                    lo, hi = sorted((tgt["r0"], src["r1"]))
                    for y in range(lo + 1, hi):
                        if out[y][x] == bg:
                            out[y][x] = src["color"]
            elif src["c0"] < tgt["c0"]:
                if src["r0"] == tgt["c1"] and not (src["c1"] < tgt["c0"] or src["c0"] > tgt["c1"]):
                    y = src["r1"]
                    lo, hi = sorted((src["c0"], tgt["c1"]))
                    for x in range(lo + 1, hi):
                        if out[y][x] == bg:
                            out[y][x] = src["color"]
            elif tgt["c0"] < src["c0"]:
                if tgt["r0"] == src["c1"] and not (tgt["c1"] < src["c0"] or tgt["c0"] > src["c1"]):
                    y = tgt["r1"]
                    lo, hi = sorted((tgt["c0"], src["c1"]))
                    for x in range(lo + 1, hi):
                        if out[y][x] == bg:
                            out[y][x] = src["color"]
    return out

def transform(grid):
    H = len(grid)
    W = len(grid[0])

    def inb(r, c):
        return 0 <= r < H and 0 <= c < W

    def same_rect(cells):
        if not cells:
            return None
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        r0, r1 = min(rs), max(rs)
        c0, c1 = min(cs), max(cs)
        if len(cells) != (r1 - r0 + 1) * (c1 - c0 + 1):
            return None
        return (r0, c0, r1, c1)

    counts = {}
    for r in range(H):
        for c in range(W):
            counts[grid[r][c]] = counts.get(grid[r][c], 0) + 1
    bg = max(sorted(counts, key=lambda x: (-counts[x], x)), key=lambda x: counts[x])

    box_color = None
    best = 0
    for val in counts:
        if val == bg:
            continue
        cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == val]
        rect = same_rect(cells)
        if rect is None:
            continue
        r0, c0, r1, c1 = rect
        inside = 0
        for rr in range(r0, r1 + 1):
            for cc in range(c0, c1 + 1):
                if grid[rr][cc] != val and grid[rr][cc] != bg:
                    inside += 1
        if inside > best:
            best = inside
            box_color = val

    if box_color is None:
        return [row[:] for row in grid]

    boxes = []
    seen = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == box_color and (r, c) not in seen:
                stack = [(r, c)]
                comp = []
                seen.add((r, c))
                while stack:
                    rr, cc = stack.pop()
                    comp.append((rr, cc))
                    for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                        nr, nc = rr + dr, cc + dc
                        if inb(nr, nc) and grid[nr][nc] == box_color and (nr, nc) not in seen:
                            seen.add((nr, nc))
                            stack.append((nr, nc))
                rect = same_rect(comp)
                if rect is None:
                    continue
                r0, c0, r1, c1 = rect
                markers = []
                for rr in range(r0, r1 + 1):
                    for cc in range(c0, c1 + 1):
                        v = grid[rr][cc]
                        if v != bg and v != box_color:
                            markers.append((rr, cc, v))
                if markers:
                    vr0 = min(m[0] for m in markers)
                    vr1 = max(m[0] for m in markers)
                    vc0 = min(m[1] for m in markers)
                    vc1 = max(m[1] for m in markers)
                    val = max(set(m[2] for m in markers), key=lambda x: sum(1 for m in markers if m[2] == x))
                    boxes.append((r0, c0, r1, c1, vr0, vc0, vr1, vc1, val))

    legend_row = None
    legend_seq = []
    for r in range(H - 1, -1, -1):
        vals = [grid[r][c] for c in range(W) if grid[r][c] != bg]
        if not vals:
            continue
        if box_color is not None and box_color in vals:
            continue
        isolated = 0
        for c, v in enumerate(vals):
            left = grid[r][c - 1] == bg if c > 0 else True
            right = grid[r][c + 1] == bg if c < W - 1 else True
            if left and right:
                isolated += 1
        if isolated == len(vals) and len(vals) >= 2:
            legend_row = r
            legend_seq = vals
            break

    out = [row[:] for row in grid]

    def bg_at(r, c):
        return grid[r][c] == bg

    def first_color(a, b):
        ia = ib = None
        for i, v in enumerate(legend_seq):
            if ia is None and v == a:
                ia = i
            if ib is None and v == b:
                ib = i
        if ia is None or ib is None:
            return None
        if abs(ia - ib) != 1:
            return None
        return legend_seq[ia] if ia < ib else legend_seq[ib]

    n = len(boxes)
    for i in range(n):
        for j in range(i + 1, n):
            A = boxes[i]
            B = boxes[j]
            ar0, ac0, ar1, ac1, arv0, acv0, arv1, acv1, av = A
            br0, bc0, br1, bc1, brv0, bcv0, brv1, bcv1, bv = B
            if av == bv:
                continue
            col = first_color(av, bv)
            if col is None:
                continue

            if ar0 <= br1 and br0 <= ar1 and ac0 == bc0 and ac1 == bc1:
                c0, c1 = acv0, acv1
                if ac1 + 1 >= br0:
                    continue
                top, bottom = (A, B) if ar1 < br0 else (B, A)
                gap0 = top[2] + 1
                gap1 = bottom[0] - 1
                if gap0 > gap1:
                    continue
                if not all(bg_at(r, c) for r in range(gap0, gap1 + 1) for c in range(c0, c1 + 1)):
                    continue
                for r in range(gap0, gap1 + 1):
                    for c in range(c0, c1 + 1):
                        out[r][c] = col

            if ac0 <= bc1 and bc0 <= ac1 and ar0 == br0 and ar1 == br1:
                r0, r1 = arv0, arv1
                if ac1 + 1 >= bc0:
                    continue
                left, right = (A, B) if ac1 < bc0 else (B, A)
                gap0 = left[3] + 1
                gap1 = right[1] - 1
                if gap0 > gap1:
                    continue
                if not all(bg_at(r, c) for r in range(r0, r1 + 1) for c in range(gap0, gap1 + 1)):
                    continue
                for r in range(r0, r1 + 1):
                    for c in range(gap0, gap1 + 1):
                        out[r][c] = col

    return out

